'use client';

import * as React from 'react';
import {createComponent} from '@lit/react';
import '@material/web/labs/gb/components/toolbar/md-gb-toolbar.js';
import {ToolbarElement} from '@material/web/labs/gb/components/toolbar/toolbar-element.js';

/**
 * A Material Design gBreeze toolbar custom element. Wraps <md-gb-toolbar>.
 * Docs: https://material-web.dev/3.0/components/toolbar/
 */
export const MdToolbar = createComponent({
  react: React,
  tagName: 'md-gb-toolbar',
  elementClass: ToolbarElement,
});

export type MdToolbarProps = React.ComponentProps<typeof MdToolbar>;
